-- 积木报表支持报表组合功能，以多sheet方式呈现
CREATE TABLE IF NOT EXISTS jimu_report_ext_data (
  id              VARCHAR(32) PRIMARY KEY COMMENT '主键ID',
  biz_type        VARCHAR(100) NOT NULL COMMENT '业务类型标识，如 report_share、temp_config 等',
  name            VARCHAR(200) DEFAULT NULL COMMENT '名称，展示用',
  descr           VARCHAR(500) DEFAULT NULL COMMENT '描述信息',
  tags            VARCHAR(255) DEFAULT NULL COMMENT '标签，多个用逗号分隔',
  data_value      LONGTEXT COMMENT '实际存储内容',
  metadata        VARCHAR(500) DEFAULT NULL COMMENT '元数据，用于存储补充信息',
  status          TINYINT DEFAULT 1 COMMENT '状态标识：1正常 0禁用',
  create_by       VARCHAR(50) DEFAULT NULL COMMENT '创建人',
  create_time     DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by       VARCHAR(50) DEFAULT NULL COMMENT '修改人',
  update_time     DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  INDEX idx_biz (biz_type)
) COMMENT='通用扩展数据表';

-- 积木报表支持多sheet报表功能
CREATE TABLE IF NOT EXISTS jimu_report_sheet (
   id VARCHAR(64) NOT NULL COMMENT '主键（Sheet ID）',
   report_id VARCHAR(64) NOT NULL COMMENT '报表ID',
   sheet_name VARCHAR(255) NOT NULL COMMENT 'Sheet名称',
   sheet_order INT NOT NULL COMMENT '排序（可以为负数，负数表示在默认sheet前面）',
   json_str LONGTEXT COMMENT '该sheet的完整jsonStr',
   create_time DATETIME COMMENT '创建时间',
   update_time DATETIME COMMENT '更新时间',
   create_by VARCHAR(64) COMMENT '创建人',
   update_by VARCHAR(64) COMMENT '更新人',
   PRIMARY KEY (id)
) COMMENT='报表Sheet表';

SET @sql = IF((SELECT COUNT(1) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'jimu_report_sheet' AND INDEX_NAME = 'idx_report_id') = 0,
'CREATE INDEX idx_report_id ON jimu_report_sheet(report_id)',
'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(1) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'jimu_report_sheet' AND INDEX_NAME = 'idx_sheet_order') = 0,
'CREATE INDEX idx_sheet_order ON jimu_report_sheet(report_id, sheet_order)',
'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(1) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'jimu_report' AND COLUMN_NAME = 'is_multi_sheet') = 0,
'ALTER TABLE `jimu_report` ADD COLUMN is_multi_sheet TINYINT COMMENT ''是否多sheet报表 1是 0否''',
'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
    
