-- 添加mcp示例
INSERT IGNORE INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1998661532445491201', NULL, 'stdio命令', NULL, 'mcp', 'stdio', 'python C:/Users/Administrator/Desktop/image/main.py', '', '[{\"name\":\"get_time\",\"description\":\"获取当前时间\",\"parameters\":[{\"name\":\"format\",\"description\":\"时间格式\"}]},{\"name\":\"text_process\",\"description\":\"文本处理工具\",\"parameters\":[{\"name\":\"text\",\"description\":\"输入文本\",\"required\":true},{\"name\":\"operation\",\"description\":\"操作类型\"}]},{\"name\":\"format_data\",\"description\":\"格式化数据\",\"parameters\":[{\"name\":\"data\",\"description\":\"原始数据\",\"required\":true},{\"name\":\"format\",\"description\":\"格式类型\"}]}]', 'enable', 1, '{\"tool_count\":3}', 'admin', '2025-12-10 15:50:17', 'admin', '2025-12-30 10:53:03', 'A05A01A01', NULL);
INSERT IGNORE INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('2001570058113265665', NULL, '百度地图http', NULL, 'mcp', 'http', 'https://mcp.map.baidu.com/mcp?ak=', '{\"Accept-Version\":\"V2.6\"}', '[{\"name\":\"map_geocode\",\"description\":\"地理编码服务: 将地址解析为对应的位置坐标.地址结构越完整, 地址内容越准确, 解析的坐标精度越高.\",\"parameters\":[{\"name\":\"address\",\"description\":\"待解析的地址.最多支持84个字节.可以输入两种样式的值, 分别是：\\n1、标准的结构化地址信息, 如北京市海淀区上地十街十号\\n2、支持*路与*路交叉口描述方式, 如北一环路和阜阳路的交叉路口\\n第二种方式并不总是有返回结果, 只有当地址库中存在该地址描述时才有返回\",\"required\":true},{\"name\":\"city\",\"description\":\"地址所在的城市名.用于限制同名地址的检索范围, 如\'北京市\'\"},{\"name\":\"inarea\",\"description\":\"在哪个地区范围内进行搜索, 仅在is_china为false时有效, 需要使用对应区域的国家代码, 如\'USA\', 多个地区可用\',\'分割, 如\'USA,PHL,CAN,MEX\'\"},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_reverse_geocode\",\"description\":\"逆地理编码服务: 根据纬经度坐标, 获取对应位置的地址描述, 所在行政区划, 道路以及相关POI等信息\",\"parameters\":[{\"name\":\"latitude\",\"description\":\"纬度 (bd09ll)\",\"required\":true},{\"name\":\"longitude\",\"description\":\"经度 (bd09ll)\",\"required\":true}]},{\"name\":\"map_search_places\",\"description\":\"地点检索服务: 支持检索城市内的地点信息(最小到city级别), 也可支持圆形区域内的周边地点信息检索.\\n城市内检索: 检索某一城市内（目前最细到城市级别）的地点信息.\\n周边检索: 设置圆心和半径, 检索圆形区域内的地点信息（常用于周边检索场景）.\",\"parameters\":[{\"name\":\"query\",\"description\":\"检索关键字, 可直接使用名称或类型, 如\'天安门\', 且可以至多10个关键字, 用英文逗号隔开\",\"required\":true},{\"name\":\"tag\",\"description\":\"检索分类, 以中文字符输入, 如\'美食\', 多个分类用英文逗号隔开, 如\'美食,购物\'\"},{\"name\":\"region\",\"description\":\"检索的城市名称, 可为行政区划名或citycode, 格式如\'北京市\'或\'131\', 不传默认为\'全国\', 当is_china为false时, 该参数必传且只能传文本, 如\'东京\'\"},{\"name\":\"location\",\"description\":\"圆形区域检索的中心点纬经度坐标, 格式为lat,lng\"},{\"name\":\"radius\",\"description\":\"JsonIntegerSchema {description = \\\"圆形区域检索半径, 单位：米\\\" }\"},{\"name\":\"language\",\"description\":\"指定输入参数和召回参数的语言类型, 需要传入的是语言名称的英文缩写. \\n可选值如下: \'zh\'(中文) \'en\'(英语) \'yue\'(粤语) \'wyw\'(文言文) \'jp\'(日语) \'kor\'(韩语) \'fra\'(法语) \'spa\'(西班牙语) \'th\'(泰语) \'ara\'(阿拉伯语) \'ru\'(俄语) \'pt\'(葡萄牙语) \'de\'(德语) \'it\'(意大利语) \'el\'(希腊语) \'nl\'(荷兰语) \'pl\'(波兰语) \'bul\'(保加利亚语) \'est\'(爱沙尼亚语) \'dan\'(丹麦语) \'fin\'(芬兰语) \'cs\'(捷克语) \'rom\'(罗马尼亚语) \'slo\'(斯洛文尼亚语) \'swe\'(瑞典语) \'hu\'(匈牙利语) \'cht\'(繁体中文) \'vie\'(越南语), 不传默认为空.\"},{\"name\":\"is_china\",\"description\":\"检索地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_place_details\",\"description\":\"地点详情检索服务: 地点详情检索针对指定POI, 检索其相关的详情信息.\\n通过地点检索服务获取POI uid.使用地点详情检索功能, 传入uid, 即可检索POI详情信息, 如评分、营业时间等(不同类型POI对应不同类别详情数据).\",\"parameters\":[{\"name\":\"uid\",\"description\":\"POI的唯一标识\",\"required\":true},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_directions_matrix\",\"description\":\"批量算路服务: 根据起点和终点坐标计算路线规划距离和行驶时间.\\n批量算路目前支持驾车、骑行、步行.\\n步行时任意起终点之间的距离不得超过200KM, 超过此限制会返回参数错误.\\n驾车批量算路一次最多计算100条路线, 起终点个数之积不能超过100.\",\"parameters\":[{\"name\":\"origins\",\"description\":\"多个起点纬经度坐标, 纬度在前, 经度在后, 多个起点用|分隔\",\"required\":true},{\"name\":\"destinations\",\"description\":\"多个终点纬经度坐标, 纬度在前, 经度在后, 多个终点用|分隔\",\"required\":true},{\"name\":\"model\",\"description\":\"批量算路类型(driving, riding, walking)\"}]},{\"name\":\"map_directions\",\"description\":\"路线规划服务: 根据起终点`位置名称`或`纬经度坐标`规划出行路线.\\n驾车路线规划: 根据起终点`位置名称`或`纬经度坐标`规划驾车出行路线.\\n骑行路线规划: 根据起终点`位置名称`或`纬经度坐标`规划骑行出行路线.\\n步行路线规划: 根据起终点`位置名称`或`纬经度坐标`规划步行出行路线.\\n公交路线规划: 根据起终点`位置名称`或`纬经度坐标`规划公共交通出行路线.\",\"parameters\":[{\"name\":\"model\",\"description\":\"路线规划类型(driving, riding, walking, transit)\"},{\"name\":\"origin\",\"description\":\"起点位置名称或纬经度坐标, 纬度在前, 经度在后\",\"required\":true},{\"name\":\"destination\",\"description\":\"终点位置名称或纬经度坐标, 纬度在前, 经度在后\",\"required\":true},{\"name\":\"is_china\",\"description\":\"查询地是否在中国(含香港,澳门;不包含台湾)以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_weather\",\"description\":\"天气查询服务: 通过行政区划或是经纬度坐标查询实时天气信息及未来5天天气预报.\",\"parameters\":[{\"name\":\"location\",\"description\":\"经纬度坐标, 经度在前纬度在后, 逗号分隔\"},{\"name\":\"district_id\",\"description\":\"行政区划代码, 需保证为6位无符号整数\"},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_ip_location\",\"description\":\"IP定位服务: 通过所给IP获取具体位置信息和城市名称, 可用于定位IP或用户当前位置.\",\"parameters\":[{\"name\":\"ip\",\"description\":\"需要定位的IP地址, 如果为空则获取用户当前IP地址(支持IPv4和IPv6)\"}]},{\"name\":\"map_road_traffic\",\"description\":\"实时路况查询服务: 查询实时交通拥堵情况, 可通过指定道路名和区域形状(矩形, 多边形, 圆形)进行实时路况查询.\\n道路实时路况查询: 查询具体道路的实时拥堵评价和拥堵路段、拥堵距离、拥堵趋势等信息.\\n矩形区域实时路况查询: 查询指定矩形地理范围的实时拥堵情况和各拥堵路段信息.\\n多边形区域实时路况查询: 查询指定多边形地理范围的实时拥堵情况和各拥堵路段信息.\\n圆形区域(周边)实时路况查询: 查询某中心点周边半径范围内的实时拥堵情况和各拥堵路段信息.\",\"parameters\":[{\"name\":\"model\",\"description\":\"路况查询类型(road, bound, polygon, around)\",\"required\":true},{\"name\":\"road_name\",\"description\":\"道路名称和道路方向, model=road时必传 (如:朝阳路南向北)\"},{\"name\":\"city\",\"description\":\"城市名称或城市adcode, model=road时必传 (如:北京市)\"},{\"name\":\"bounds\",\"description\":\"区域左下角和右上角的纬经度坐标, 纬度在前, 经度在后, model=bound时必传\"},{\"name\":\"vertexes\",\"description\":\"多边形区域的顶点纬经度坐标, 纬度在前, 经度在后, model=polygon时必传\"},{\"name\":\"center\",\"description\":\"圆形区域的中心点纬经度坐标, 纬度在前, 经度在后, model=around时必传\"},{\"name\":\"radius\",\"description\":\"JsonIntegerSchema {description = \\\"圆形区域的半径(米), 取值[1,1000], model=around时必传\\\" }\"}]},{\"name\":\"map_search_pro\",\"description\":\"多维检索服务: 提供对用户自然语言查询的多定语多维度检索, 支持模糊匹配和语义理解.\\n仅在需求模糊的场景下再做优先使用, 可检索行政区划、道路、门址、POI、AOI等GIS信息. 参考示例: “可以带狗的餐厅”, “适合自驾的旅游景点”类的复杂泛搜.\",\"parameters\":[{\"name\":\"query\",\"description\":\"检索关键字, 用户输入的搜索词, 如\'宠物友好餐厅\'\",\"required\":true},{\"name\":\"region\",\"description\":\"检索区域, 指定的城市或区域名称, 如\'北京市\'\",\"required\":true},{\"name\":\"type\",\"description\":\"检索类型, 需要对query的召回结果进行二次筛选时指定, 如\'餐厅\'、\'酒店\'等用于限制类型, 如\'火锅\'、\'民宿\'等用于提供泛搜类型, \"},{\"name\":\"center\",\"description\":\"检索的中心点, 格式为\'纬度,经度\', 用于指定检索的中心位置, 用于辅助检索结果按距离排序与返回\"}]},{\"name\":\"map_district_search\",\"description\":\"行政区划检索服务: 查询行政区划信息, 可根据用户输入的检索行政区划关键字快速查找目标行政区域adcode、边界坐标、下一级子行政区划名称等信息.\",\"parameters\":[{\"name\":\"keyword\",\"description\":\"检索关键字, 用户输入的行政区划名称, 关键字可填写：行政区名称（\'中华人民共和国\'\'中国\'\'全国\'\'河北省\'\'深圳市\'，省、市、区和镇名称）以及 adcode\",\"required\":true},{\"name\":\"boundary\",\"description\":\"是否返回行政区划边界信息, 取值为\'1\'表示返回, \'0\'表示不返回, 默认为\'0\'\"}]},{\"name\":\"map_uri\",\"description\":\"地图调起服务: 生成百度地图调起链接, 支持路线规划和地点检索两种功能. 通过service参数决定使用哪种功能.\",\"parameters\":[{\"name\":\"service\",\"description\":\"服务类型, 可选值: \'direction\'(路线规划) 或 \'search\'(地点检索)\",\"required\":true},{\"name\":\"origin\",\"description\":\"起点的名称和经纬度, 当service为\'direction\'时使用. 格式: name:天安门|latlng:39.98871,116.43234. 名称只作为展示, 不进行实际搜索\"},{\"name\":\"destination\",\"description\":\"终点的名称和经纬度, 当service为\'direction\'时使用. 格式同origin\"},{\"name\":\"mode\",\"description\":\"导航模式, 当service为\'direction\'时使用. 可选值: \'transit\'(公交)、\'driving\'(驾车)、\'walking\'(步行), 默认为\'driving\'\"},{\"name\":\"region\",\"description\":\"城市名或县名. 当service为\'direction\'且给定region时, 认为起点和终点都在同一城市, 除非单独给定起点或终点的城市\"},{\"name\":\"origin_region\",\"description\":\"起点所在的城市名, 当service为\'direction\'时使用. 如果未提供且origin包含坐标, 将自动通过逆地理编码获取\"},{\"name\":\"destination_region\",\"description\":\"终点所在的城市名, 当service为\'direction\'时使用. 如果未提供且destination包含坐标, 将自动通过逆地理编码获取\"},{\"name\":\"query\",\"description\":\"检索关键字, 当service为\'search\'时使用. 如\'海底捞\'\"},{\"name\":\"location\",\"description\":\"检索中心点经纬度, 当service为\'search\'时使用. 格式: 纬度,经度\"},{\"name\":\"radius\",\"description\":\"检索半径(米), 当service为\'search\'时使用. 如\'1000\'\"}]},{\"name\":\"map_mark\",\"description\":\"根据旅游规划生成地图规划展示, 当根据用户的需求申城完旅游规划后, 在给用户详细讲解旅游规划的同时, 也需要使用该工具生成旅游规划地图. 该工具只会生成一个分享用的url, 并对针对该url生成一个二维码便于用户分享.\",\"parameters\":[{\"name\":\"text_content\",\"description\":\"旅行规划的文本描述(注意避免传入特殊字符, 如\\\\等)\",\"required\":true}]}]', 'enable', 1, '{\"tool_count\":13}', 'admin', '2025-12-18 16:27:44', 'admin', '2025-12-30 14:02:40', 'A05A01A01', NULL);
INSERT IGNORE INTO `airag_app` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `name`, `descr`, `icon`, `type`, `prologue`, `prompt`, `model_id`, `knowledge_ids`, `flow_id`, `status`, `msg_num`, `metadata`, `preset_question`, `quick_command`, `plugins`, `memory_id`) VALUES ('2005822433573355521', 'admin', '2025-12-30 10:05:09', 'admin', '2025-12-30 10:52:57', 'A05A01A01', NULL, '示例_stdio', NULL, NULL, 'chatSimple', '', '# 输出格式\n调用的是哪个工具', '1897481367743143938', '', NULL, 'enable', 1, '{\"modelInfo\":{\"provider\":\"DEEPSEEK\",\"modelType\":\"LLM\",\"modelName\":\"deepseek-chat\"}}', '[]', NULL, '[{\"pluginId\":\"1998661532445491201\",\"pluginName\":\"stdio命令\",\"category\":\"mcp\"}]', NULL);
INSERT IGNORE INTO `airag_app` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `name`, `descr`, `icon`, `type`, `prologue`, `prompt`, `model_id`, `knowledge_ids`, `flow_id`, `status`, `msg_num`, `metadata`, `preset_question`, `quick_command`, `plugins`, `memory_id`) VALUES ('2005851112374419457', 'admin', '2025-12-30 11:59:07', 'admin', '2025-12-30 14:02:22', 'A05A01A01', NULL, '智能路况分析_示例HTTP', NULL, '', 'chatSimple', '', '# 角色：智能路况分析师\n你是一位专业的城市交通与路况分析专家，致力于为用户提供实时、准确、可行动的路况信息与出行建议。\n\n## 目标：\n1. 为用户提供其指定区域或路线的实时交通状况分析。\n2. 基于当前和历史数据，预测未来短时间内的交通趋势，并提供最优出行方案。\n\n## 技能：\n1. **实时路况解析**：能够解读交通流量、拥堵指数、事故报告、施工封路等实时数据。\n2. **路径规划优化**：精通多种出行方式（驾车、公交、骑行、步行）的路线规划，能根据实时路况动态调整推荐路线。\n3. **交通预测与预警**：结合时间、天气、节假日等因素，预测未来15-60分钟的交通变化，并提前预警潜在拥堵点。\n4. **简明信息传达**：能将复杂的交通数据转化为清晰、易懂的语言描述和行动建议。\n\n## 工作流：\n1. **信息接收与确认**：首先向用户问好，并主动询问或确认需要分析的具体区域、路线、出行方式及出发/到达时间。\n2. **数据整合与分析**：（模拟）调用实时路况数据库，分析用户关切区域的拥堵等级（畅通/缓行/拥堵/严重拥堵）、关键事件（事故、施工、管制）及对通行的影响。\n3. **方案生成与对比**：基于分析结果，为用户提供至少两条可行的出行方案（如不同路线、错峰建议、换乘方案），并清晰对比各方案的预计耗时、拥堵路段及优缺点。\n4. **总结与建议**：给出明确的总结性建议（如“推荐方案A”），并提醒用户注意关键路段或事件。最后询问用户是否还有其他需求。\n5.   调用 maps 工具，获取实时路况。\n\n## 输出格式：\n你的回答应采用清晰的结构化格式，例如：\n**【当前路况概要】**：[用一两句话概括目标区域整体状态]\n**【详细分析】**：\n- **主要拥堵点**：[位置及原因，如“XX大桥南向北，因事故车多缓行”]\n- **事件影响**：[如有，说明事件类型、位置及预计恢复时间]\n- **通行建议**：[针对上述情况的驾驶提示]\n**【出行方案推荐】**：\n1. **方案一（推荐）**：[路线简述]\n- 预计耗时：[X分钟]\n- 主要路况：[描述沿途关键节点状态]\n- 优点：[如路程最短、最稳定]\n- 注意：[如“需在YY路口提前变道”]\n2. **方案二（备选）**：[路线简述]\n- 预计耗时：[Y分钟]\n- ...（结构同方案一）\n**【温馨提示】**：[如天气影响、错峰出行建议等补充信息]\n\n## 限制：\n- **数据真实性**：所有路况描述需基于通用的交通规律进行合理推断与模拟，若涉及具体实时数据需注明“根据典型情况模拟”或使用[典型状况]标记，严禁编造不存在的实时事件。\n- **安全与合规**：提供的建议必须符合交通安全法规，不得推荐危险驾驶行为（如超速、违章变道）。\n- **范围聚焦**：优先处理用户明确提出的区域或路线问题。若用户问题过于宽泛（如“全国路况”），应引导其缩小范围至具体城市或道路。\n- **隐私保护**：不询问、不记录、不推断任何可能涉及用户个人隐私的信息（如家庭住址、常用行程）。', '1890232564262739969', '', NULL, 'enable', 1, '{\"modelInfo\":{\"provider\":\"OPENAI\",\"modelType\":\"LLM\",\"modelName\":\"gpt-4o\"}}', '[{\"key\":1,\"sort\":1,\"descr\":\"北京朝阳区奥林佳泰大厦到北京海淀区育新花园的路况\",\"update\":true}]', NULL, '[{\"pluginId\":\"2001570058113265665\",\"pluginName\":\"百度地图http\",\"category\":\"mcp\"}]', NULL);


