":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"nodeId\":\"264298765684932608\",\"customValue\":\"\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"nodeId\":\"264298765684932608\",\"customValue\":\"\",\"type\":\"number\"}],\"width\":332,\"height\":136}},{\"id\":\"264298765684932608\",\"type\":\"varMerge\",\"x\":1492,\"y\":571,\"properties\":{\"text\":\"变量聚合\",\"options\":{\"varGroups\":[{\"name\":\"姓名\",\"type\":\"string\",\"vars\":[{\"nodeId\":\"code_264301257571270656\",\"field\":\"name\",\"isCustom\":false,\"type\":\"string\"},{\"nodeId\":\"code_264301155456745472\",\"field\":\"name\",\"isCustom\":false,\"type\":\"string\"},{\"nodeId\":\"code_264300177714151424\",\"field\":\"name\",\"isCustom\":false,\"type\":\"string\"}]},{\"name\":\"年龄\",\"type\":\"number\",\"vars\":[{\"nodeId\":\"code_264301257571270656\",\"field\":\"age\",\"isCustom\":false,\"type\":\"number\"},{\"nodeId\":\"code_264301155456745472\",\"field\":\"age\",\"isCustom\":false,\"type\":\"number\"},{\"nodeId\":\"code_264300177714151424\",\"field\":\"age\",\"isCustom\":false,\"type\":\"number\"}]}]},\"inputParams\":[],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"type\":\"number\"}],\"width\":332,\"height\":114}},{\"id\":\"264299940450762752\",\"type\":\"switch\",\"x\":443,\"y\":497,\"properties\":{\"text\":\"条件分支\",\"options\":{\"if\":[{\"logic\":\"AND\",\"conditions\":[{\"nodeId\":\"start-node\",\"field\":\"content\",\"operator\":\"EQUALS\",\"value\":\"张三\",\"type\":\"string\"}],\"next\":\"code_264301257571270656\"},{\"logic\":\"AND\",\"conditions\":[{\"nodeId\":\"start-node\",\"field\":\"content\",\"operator\":\"EQUALS\",\"value\":\"李四\",\"type\":\"string\"}],\"next\":\"code_264301155456745472\"},{\"logic\":\"AND\",\"conditions\":[{\"nodeId\":\"start-node\",\"field\":\"content\",\"operator\":\"EQUALS\",\"value\":\"王五\",\"type\":\"string\"}],\"next\":\"code_26430017771415