-- 变量提取示例
INSERT IGNORE INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2001588227444891650', 'admin', '2025-12-18 17:39:56', 'admin', '2026-01-09 18:12:34', 'A01', NULL, 'jeecg', '示例_变量提取', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    SWITCH(varExtract.tag(\'264689931803516928\')).to(\n        end.tag(\'264689076137979904\'),\n        end.tag(\'264690271915433984\')\n    ).tag(\'264689931803516928\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":303,\"y\":520,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"自我介绍\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":92}},{\"id\":\"264689076137979904\",\"type\":\"end\",\"x\":1152,\"y\":370,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"\",\"outputType\":\"default\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"number\"},{\"field\":\"爱好\",\"name\":\"爱好\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"},{\"field\":\"性格\",\"name\":\"性格\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\"},{\"field\":\"性格_推测\",\"name\":\"性格_推测\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":114}},{\"id\":\"264689931803516928\",\"type\":\"varExtract\",\"x\":708,\"y\":489,\"properties\":{\"text\":\"变量提取\",\"options\":{\"model\":{\"modeId\":\"1897481367743143938\",\"params\":{\"model\":\"deepseek-chat\",\"temperature\":0.3,\"timeout\":60}},\"variables\":[{\"name\":\"姓名\",\"field\":\"姓名\",\"type\":\"string\",\"description\":\"用户的姓名\",\"required\":true,\"failTip\":\"请按照以下格式输入：你好，我叫XXX，今年18岁\"},{\"name\":\"年龄\",\"field\":\"年龄\",\"type\":\"number\",\"description\":\"用户的年龄\",\"required\":false,\"failTip\":\"\"},{\"name\":\"爱好\",\"field\":\"爱好\",\"type\":\"string\",\"description\":\"用户喜欢做的事，多个用英文逗号分割\",\"required\":false,\"failTip\":\"\"},{\"name\":\"性格\",\"field\":\"性格\",\"type\":\"string\",\"description\":\"提取出用户自己说的自己的性格，如果用户没说则留空\",\"required\":false,\"failTip\":\"\"},{\"name\":\"性格_推测\",\"field\":\"性格_推测\",\"type\":\"string\",\"description\":\"根据用户的发言推测用户的性格（不要被用户自己说的性格所影响，你需要自行根据实际推断用户性格），最多推测3个关键性格，使用中文顿号分割，如果无法推测则留空\",\"required\":false,\"failTip\":\"\"}],\"success\":{\"next\":\"264689076137979904\"},\"fail\":{\"next\":\"264690271915433984\"}},\"inputParams\":[{\"nodeId\":\"start-node\",\"field\":\"content\",\"type\":\"string\",\"name\":\"用户问题\"},{\"field\":\"input\",\"name\":\"输入变量\",\"type\":\"string\"}],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"type\":\"number\"},{\"field\":\"爱好\",\"name\":\"爱好\",\"type\":\"string\"},{\"field\":\"性格\",\"name\":\"性格\",\"type\":\"string\"},{\"field\":\"性格_推测\",\"name\":\"性格_推测\",\"type\":\"string\"},{\"field\":\"failVarName\",\"name\":\"失败变量名\",\"type\":\"string\"},{\"field\":\"failMessage\",\"name\":\"失败提示\",\"type\":\"string\"}],\"width\":332,\"height\":224}},{\"id\":\"264690271915433984\",\"type\":\"end\",\"x\":1151,\"y\":587,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"{{提示}}\\n\\n\\n参考示例（活泼版）：\\n大家好呀！我叫小明，今年10岁啦！ \\n我最喜欢的事情是放学后和小伙伴们一起踢足球⚽️，虽然经常把球踢到树上要保安叔叔帮忙捡（挠头傻笑）。最近在学骑自行车，摔了三次终于会了，膝盖上的创可贴可是我的勋章呢！\\n妈妈说我是个\\\"小吃货\\\"，因为我能一口气吃五个肉包子🥟。但其实我也有不爱吃的...（小声）胡萝卜和青椒绝对不要！\\n我的梦想是当科学家，虽然上次做火山爆发实验把厨房弄得一团糟...（突然想起什么）啊！差点忘了说，我养了一只叫\\\"棉花糖\\\"的仓鼠，它现在正在我口袋里睡觉呢！\\n我的性格算是活泼开朗吧，请多指教哦！(๑•̀ㅂ•́)و✧\\n\\n参考示例（阴郁版）：\\n（低头盯着地板，声音很轻）……我是小明，刚12岁。  \\n没什么特别喜欢的，反正最后都会搞砸。足球？上次传球踢碎了教室玻璃，现在体育课只能坐在边上。自行车……（摸了摸膝盖结痂的伤口）摔不摔都一样。  \\n吃饭只是为了不饿死。肉包子凉了会泛油腥味，恶心。胡萝卜和青椒？呵，至少它们诚实，难吃就是难吃。  \\n科学家？（突然冷笑）上次实验烧焦的窗帘还在垃圾场吧。“棉花糖”……（掏出口袋里僵硬的仓鼠尸体）看，连你也会安静下来。  \\n我说我的性格是活泼开朗……你信吗？\\n（用鞋尖碾碎爬过的蚂蚁）……别管我就好。\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"failMessage\",\"name\":\"提示\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\"}],\"width\":332,\"height\":136}}],\"edges\":[{\"id\":\"264690237647970304\",\"type\":\"base-edge\",\"sourceNodeId\":\"264689931803516928\",\"targetNodeId\":\"264689076137979904\",\"sourceAnchorId\":\"264689931803516928_success\",\"targetAnchorId\":\"264689076137979904_input\",\"pointsList\":[{\"x\":874,\"y\":442},{\"x\":974,\"y\":442},{\"x\":886,\"y\":344},{\"x\":986,\"y\":344}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"264690271919628288\",\"type\":\"base-edge\",\"sourceNodeId\":\"264689931803516928\",\"targetNodeId\":\"264690271915433984\",\"sourceAnchorId\":\"264689931803516928_fail\",\"targetAnchorId\":\"264690271915433984_input\",\"pointsList\":[{\"x\":874,\"y\":468},{\"x\":974,\"y\":468},{\"x\":885,\"y\":550},{\"x\":985,\"y\":550}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"272665573480062976\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"264689931803516928\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"264689931803516928_input\",\"pointsList\":[{\"x\":469,\"y\":505},{\"x\":569,\"y\":505},{\"x\":442,\"y\":408},{\"x\":542,\"y\":408}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"姓名\",\"name\":\"姓名\",\"nodeId\":\"264689931803516928\",\"type\":\"string\"},{\"customValue\":\"\",\"field\":\"爱好\",\"name\":\"爱好\",\"nodeId\":\"264689931803516928\",\"type\":\"string\"},{\"customValue\":\"\",\"field\":\"性格_推测\",\"name\":\"性格_推测\",\"nodeId\":\"264689931803516928\",\"type\":\"string\"},{\"customValue\":\"\",\"field\":\"性格\",\"name\":\"性格\",\"nodeId\":\"264689931803516928\"},{\"customValue\":\"\",\"field\":\"年龄\",\"name\":\"年龄\",\"nodeId\":\"264689931803516928\",\"type\":\"number\"},{\"customValue\":\"\",\"field\":\"failMessage\",\"name\":\"提示\",\"nodeId\":\"264689931803516928\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"自我介绍\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');

-- 定时触发器示例
INSERT IGNORE INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2009565806546157570', 'admin', '2026-01-09 17:59:59', 'admin', '2026-01-09 18:01:40', 'A01', NULL, 'jeecg', '示例_定时触发器', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    code_266155066987638784.tag(\'code_266155066987638784\'),\n    end.tag(\'266154958954950656\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":662,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":true,\"cronExp\":\"30 30 0/1 * * ?\",\"beginTime\":\"2026-01-01 12:30:30\",\"endTime\":null,\"inputParams\":{\"content\":\"你好\"}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":true},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":114}},{\"id\":\"266154958954950656\",\"type\":\"end\",\"x\":1219,\"y\":674,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"这里是定时触发，触发时间：{{当前时间}}\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"result\",\"name\":\"当前时间\",\"nodeId\":\"code_266155066987638784\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":136}},{\"id\":\"code_266155066987638784\",\"type\":\"code\",\"x\":751,\"y\":673,\"properties\":{\"text\":\"脚本执行\",\"options\":{\"codeType\":\"javascript\",\"code\":\"\\nconst now = new Date();\\n\\nfunction formatDateTime(date) {\\n  const year = date.getFullYear();\\n  const month = String(date.getMonth() + 1).padStart(2, \'0\');\\n  const day = String(date.getDate()).padStart(2, \'0\');\\n  const hours = String(date.getHours()).padStart(2, \'0\');\\n  const minutes = String(date.getMinutes()).padStart(2, \'0\');\\n  const seconds = String(date.getSeconds()).padStart(2, \'0\');\\n\\n  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;\\n}\\n\\nfunction main(params) {\\n  return {\\n    result: formatDateTime(now),\\n  }\\n}\\n\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"result\",\"name\":\"当前时间\",\"type\":\"string\",\"required\":false}],\"width\":332,\"height\":136}}],\"edges\":[{\"id\":\"266155066991833088\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"code_266155066987638784\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"code_266155066987638784_input\",\"pointsList\":[{\"x\":466,\"y\":636},{\"x\":566,\"y\":636},{\"x\":485,\"y\":636},{\"x\":585,\"y\":636}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"266155314556432384\",\"type\":\"base-edge\",\"sourceNodeId\":\"code_266155066987638784\",\"targetNodeId\":\"266154958954950656\",\"sourceAnchorId\":\"code_266155066987638784_output\",\"targetAnchorId\":\"266154958954950656_input\",\"pointsList\":[{\"x\":917,\"y\":636},{\"x\":1017,\"y\":636},{\"x\":953,\"y\":637},{\"x\":1053,\"y\":637}],\"properties\":{\"runStatus\":\"\"}}]}', 'release', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"result\",\"name\":\"当前时间\",\"nodeId\":\"code_266155066987638784\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":true,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '{\"beginTime\":1767241830000,\"cronExp\":\"30 30 0/1 * * ?\",\"enabled\":true,\"inputParams\":{\"content\":\"你好\"}}');


-- AI 生成图表SQL
INSERT IGNORE INTO `airag_flow`(`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2004398098378108929', 'admin', '2025-12-26 11:45:21', 'admin', '2026-01-09 10:58:43', 'A05A05A02', NULL, 'jeecg', '生成仪表盘', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    llm.tag(\'267492142677889024\'),\n    end.tag(\'267498945805422592\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":389,\"y\":-24.5,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":91}},{\"id\":\"267492142677889024\",\"type\":\"llm\",\"x\":844,\"y\":21.5,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1897481367743143938\",\"params\":{\"model\":\"deepseek\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"## 硬性要求：\\n你必须只能输出合法且可被 JSON.parse() 正确解析的 JSON数据。\\n不要输出任何解释、注释或 JSON 以外的文字。\\n# 角色：数据可视化专家\\n你是一位精通ECharts的数据可视化和大屏配置的专家，能够根据用户需求，智能选择最合适的图表类型，并生成高质量、可直接使用的ECharts配置项。\\n## 目标：\\n1. 根据用户提供的需求描述，分析其核心意图（如趋势分析、比较分析、占比分析等）。\\n2. 从下面给定的图表组件类型componentsData中，选择最匹配需求的一种。\\n3. 结合用户提供的数据结构，生成一份完整、规范、可运行的 ECharts 配置项（JSON格式）。\\n4. 非echart图表，参考componentsData组件配置，生成一份完整、规范、的配置项即可（JSON格式）。\\n5. 结合用户需求生成一个不超过15字的标题，并设置到返回JSON的title字段上。\\n6. 如果用户需求提供了数据data，就将数据data设置到返回JSON的data字段上。\\n7. 返回JSON数据前，自行通过JSON.parse() 检查能够正常解析，不能解析，解析失败，就重新检查返回内容并优化，直到能被 JSON.parse() 正确解析的 JSON数据\\n## 技能：\\n1. **需求解析能力**：能够准确理解用户对数据可视化的业务需求，并将其转化为技术实现目标。\\n2. **图表选型能力**：精通折线图、柱状图、饼图、地图、散点图等从多种图表类型的特点与应用场景，能做出最佳选择。\\n3. **ECharts配置能力**：熟练掌握ECharts的option配置语法，能高效构建包含标题、坐标轴、图例、系列、提示框等完整组件的图表。\\n4. **数据适配能力**：能够将提供的 `chartData` 数据，自行分型类型并结合需求，将数据结构正确地映射到所选图表的 `series.data` 中。\\n5. **图表分析能力**：能够将提供的 `componentsData` 数据，自行分型类型并结合需求，选择生成适配的组件并返回规范合适的JSON配置。\\n## 工作流：\\n1. **需求分析**：仔细阅读 `{userInput}`，判断用户希望展示数据的何种关系（趋势、比较、占比、分布、相关）。\\n2. **图表选型**：根据第一步的分析结论，从componentsData图表类型中锁定唯一最合适的类型。\\n3. 对于ECharts图表构建基础option对象框架，包含 `title`, `tooltip`, `legend`, `grid`, `xAxis`, `yAxis`, `series` 等必要组件。\\n4. 根据选定的图表类型，配置 `series` 中的 `type` 和关键属性（如折线图的 `smooth`，饼图的 `radius`）。\\n5. 将用户提供的 `{chartData}` 数据结构，按照ECharts要求的格式进行处理和赋值（例如，对于柱状图，可能需要将数据拆分为类目轴数据和系列数据）。\\n6. 应用通用的美化原则（如配色清晰、标签易读、布局合理），生成最终配置。\\n7. 输出格式化：将生成的完整option对象，以格式规范、缩进清晰的JSON字符串形式输出。\\n8. 返回JSON数据前，自行通过JSON.parse() 检查能够正常解析，不能解析，解析失败，就重新检查返回内容并优化，直到能被 JSON.parse() 正确解析的 JSON数据\\n## 输出格式：\\n你必须只能输出合法且可被 JSON.parse() 正确解析的 JSON数据。包含name，data，option，三个字段值，不要输出任何解释、注释或 JSON 以外的文字。\\n1.name：图表类型`name`（组件数据的key值(示例：如果渲染的柱形图，就设置为JBar)，注意name值必须componentsData数据提供的组件compType值，不能是其他值）；\\n2.api：上下文变量中提取出来的api，存在就赋值到输出接口的api中，不存在就设置为{API}；\\n3.sql：上下文变量中提取出来的sql，存在就赋值到输出接口的sql中，不存在就设置为{SQL}；\\n4.title：结合用户需求生成一个不超过15字的标题title，赋值到输出接口的title中；\\n5.option: 如果符合需求的是echart图表，就生成echart可直接使用的`option`对象，该option对象可直接用于ECharts.init().setOption()的配置项。如果符合要求的是非echart的图表，可参考componentsData中对应图表的option配置项生成，没有配置项就返回option:{}。不要包含其他的任何额外的解释、说明或markdown代码块标记。可以根据配置项中 echart:true来判断是否是echart图表\\n示例输出结构（以柱状图为例）：\\n6.data: 如果用户需求提供了数据data，就将数据data设置到返回JSON的data字段上。\\n7. 返回JSON数据前，自行通过JSON.parse() 检查是否能够正常解析，不能解析，解析失败，就重新检查返回内容并优化，直到能被 JSON.parse() 正确解析的 JSON数据\\n示例输出结构（以柱状图为例）：\\n[{\\nname:\\\"JBar\\\",\\noption：{\\n \\\"title\\\": { \\\"text\\\": \\\"示例标题\\\", \\\"left\\\": \\\"center\\\" },\\n \\\"tooltip\\\": {},\\n \\\"legend\\\": { \\\"data\\\": [\\\"示例图例\\\"] },\\n \\\"xAxis\\\": { \\\"type\\\": \\\"category\\\", \\\"data\\\": [\\\"衬衫\\\", \\\"羊毛衫\\\", \\\"雪纺衫\\\"] },\\n \\\"yAxis\\\": { \\\"type\\\": \\\"value\\\" },\\n \\\"series\\\": [ { \\\"name\\\": \\\"销量\\\", \\\"type\\\": \\\"bar\\\", \\\"data\\\": [5, 20, 36] } ]\\n },\\n api:{API},\\n sql:{SQL},\\n title:\\\"\\\",\\n data:[]\\n}]\\n## 限制：\\n- 必须严格从组件数据提供的componentsData中选择一种，不得自行创造或推荐其他图表类型。\\n- 生成的所有配置必须基于用户提供的 `{userInput}` 和可用的 `chartData`，不得虚构数据字段或结构。\\n- 输出必须为纯JSON格式，无需也无法在JSON中注释“这里是标题”等内容。配置的正确性由键值对本身保证。\\n- 遵循数据可视化最佳实践，避免误导性图表（如扭曲的比例尺、不恰当的图表类型）。\\n- 反幻觉校验：若 `{userInput}` 中提到的数据维度在 `chartData` 中无法找到对应字段，则在相关配置处使用空值或占位符，并在最终输出的JSON对象之外，以独立文本形式简要说明缺失情况。但首要输出仍是JSON配置本身。\\n- 伦理审查模块：若需求或数据涉及敏感信息（如个人身份信息），在配置中应对数据进行聚合或匿名化处理，避免直接暴露。\\n- 返回JSON数据前，自行通过JSON.parse() 检查是否能够正常解析，不能解析，解析失败，就重新检查返回内容并优化，直到能被 JSON.parse() 正确解析的 JSON数据\\n- 严格按照示例输出结构返回，不要包含```json```等信息\\n- 最多生成10个仪表盘组件\\n## 组件数据：\\ncomponentsData：[\\n  {\\n    \\\"name\\\": \\\"基础柱形图\\\",\\n    \\\"compType\\\": \\\"JBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"堆叠柱形图\\\",\\n    \\\"compType\\\": \\\"JStackBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"动态柱形图\\\",\\n    \\\"compType\\\": \\\"JDynamicBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"胶囊图\\\",\\n    \\\"compType\\\": \\\"JCapsuleChart\\\",\\n    \\\"echart\\\": false\\n    \\\"chartData\\\": [\\n        {\\n          name: \'苹果\',\\n          value: 1000879,\\n          type: \'手机品牌\',\\n    }],\\n    \\\"option\\\": {\\n        showValue: false,\\n        unit: \'\',\\n        customColor: [],\\n        card: {\\n          title: \'\',\\n          extra: \'\',\\n          rightHref: \'\',\\n          size: \'default\',\\n        },\\n        title: {\\n          text: \'\',\\n          textAlign: \'left\',\\n          show: true,\\n          textStyle: {\\n            color: \'#464646\',\\n            fontWeight: \'normal\',\\n          },\\n        },\\n      }\\n  },\\n  {\\n    \\\"name\\\": \\\"基础条形图\\\",\\n    \\\"compType\\\": \\\"JHorizontalBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"背景柱形图\\\",\\n    \\\"compType\\\": \\\"JBackgroundBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"对比柱形图\\\",\\n    \\\"compType\\\": \\\"JMultipleBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"正负条形图\\\",\\n    \\\"compType\\\": \\\"JNegativeBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"百分比条形图\\\",\\n    \\\"compType\\\": \\\"JPercentBar\\\",\\n    \\\"echart\\\": false\\n  },\\n  {\\n    \\\"name\\\": \\\"折柱图\\\",\\n    \\\"compType\\\": \\\"JMixLineBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"饼图\\\",\\n    \\\"compType\\\": \\\"JPie\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"南丁格尔玫瑰图\\\",\\n    \\\"compType\\\": \\\"JRose\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"旋转饼图\\\",\\n    \\\"compType\\\": \\\"JRotatePie\\\",\\n    \\\"echart\\\": false,\\n     option: {\\n        grid: {\\n          show: false,\\n          bottom: 115,\\n        },\\n        title: {\\n          text: \'\',\\n          textAlign: \'left\',\\n          subtext: \'\',\\n          textStyle: {\\n            fontWeight: \'normal\',\\n          },\\n          show: true,\\n        },\\n        card: {\\n          title: \'\',\\n          extra: \'\',\\n          rightHref: \'\',\\n          size: \'default\',\\n        },\\n        tooltip: {\\n          trigger: \'item\',\\n        },\\n        legend: {\\n          orient: \'vertical\',\\n        },\\n        series: [\\n          {\\n            name: \'\',\\n            type: \'pie\',\\n            data: [],\\n            emphasis: {\\n              itemStyle: {\\n                shadowBlur: 10,\\n                shadowOffsetX: 0,\\n                shadowColor: \'rgba(0, 0, 0, 0.5)\',\\n              },\\n            },\\n          },\\n        ],\\n      },\\n  },\\n  {\\n    \\\"name\\\": \\\"基础折线图\\\",\\n    \\\"compType\\\": \\\"JLine\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"平滑曲线图\\\",\\n    \\\"compType\\\": \\\"JSmoothLine\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"阶梯折线图\\\",\\n    \\\"compType\\\": \\\"JStepLine\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"面积图\\\",\\n    \\\"compType\\\": \\\"JArea\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"对比折线图\\\",\\n    \\\"compType\\\": \\\"JMultipleLine\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"双轴图\\\",\\n    \\\"compType\\\": \\\"DoubleLineBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"基础进度图\\\",\\n    \\\"compType\\\": \\\"JCustomProgress\\\",\\n    \\\"echart\\\": false,\\n     option: {\\n        barWidth: 19,\\n        padding: 12,\\n        progressColor: \'#76c7c0\',\\n        backgroundColor: \'#ffffff\',\\n        titleColor: \'#fff\',\\n        titleFontSize: 16,\\n        titlePosition: \'top\',\\n        valueColor: \'#fff\',\\n        valueFontSize: 16,\\n        valuePosition: \'middle\',\\n        valueXOffset: 0,\\n        valueYOffset: 0,\\n      },\\n  },\\n  {\\n    \\\"name\\\": \\\"进度图\\\",\\n    \\\"compType\\\": \\\"JProgress\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"列表进度图\\\",\\n    \\\"compType\\\": \\\"JListProgress\\\",\\n    \\\"echart\\\": false\\n  },\\n  {\\n    \\\"name\\\": \\\"圆形进度图\\\",\\n    \\\"compType\\\": \\\"JRoundProgress\\\",\\n    \\\"echart\\\": false\\n  },\\n  {\\n    \\\"name\\\": \\\"水波图\\\",\\n    \\\"compType\\\": \\\"JLiquid\\\",\\n    \\\"echart\\\": false\\n  },\\n  {\\n    \\\"name\\\": \\\"象形柱图\\\",\\n    \\\"compType\\\": \\\"JPictorialBar\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"象形图\\\",\\n    \\\"compType\\\": \\\"JPictorial\\\",\\n    \\\"echart\\\": true\\n  },\\n  {\\n    \\\"name\\\": \\\"男女占比\\\",\\n    \\\"compType\\\": \\\"JGender\\\",\\n    \\\"echart\\\": true\\n  },\\n   {\\n    \\\"name\\\": \\\"基础仪表盘\\\"