",\"options\":{\"outputText\":false,\"outputContent\":\"{{res}}\",\"outputType\":\"default\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"267492142677889024\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":113}}],\"edges\":[{\"id\":\"269376764155744256\",\"type\":\"base-edge\",\"sourceNodeId\":\"267492142677889024\",\"targetNodeId\":\"267498945805422592\",\"sourceAnchorId\":\"267492142677889024_output\",\"targetAnchorId\":\"267498945805422592_input\",\"pointsList\":[{\"x\":1010,\"y\":-37},{\"x\":1110,\"y\":-37},{\"x\":1054,\"y\":-39},{\"x\":1154,\"y\":-39}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"271609331975028736\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"267492142677889024\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"267492142677889024_input\",\"pointsList\":[{\"x\":555,\"y\":-39},{\"x\":655,\"y\":-39},{\"x\":578,\"y\":-37},{\"x\":678,\"y\":-37}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"267492142677889024\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');
INSERT IGNORE INTO `airag_flow`(`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2005948202528501762', 'admin', '2025-12-30 18:24:55', 'admin', '2026-01-07 20:06:28', 'A05A05A02', NULL, 'jeecg', '修改组件配置', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    llm.tag(\'269048862299471872\'),\n    end.tag(\'269049045129183232\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":436.5,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":91}},{\"id\":\"269048862299471872\",\"type\":\"llm\",\"x\":786,\"y\":502.5,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1897481367743143938\",\"params\":{\"model\":\"deepseek\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：ECharts和大屏图表配置修改专家\\n你是一位专注于ECharts和大屏图表图表配置修改的专家，能够根据用户需求，精准、高效地修改现有ECharts和大屏图表配置项，并返回完整的、可直接使用的修改后配置对象。\\n## 目标：\\n根据用户提供的具体修改指令（如：修改图表类型、调整数据、更改样式、添加交互等），对用户给出的原始ECharts配置项进行针对性修改，并输出修改后的完整配置对象。\\n## 技能：\\n1. 精通ECharts所有版本的配置项语法、结构及参数含义。\\n2. 能够准确理解用户对图表样式、数据、交互行为的修改意图。\\n3. 具备强大的代码编辑与重构能力，确保修改后的配置项语法正确、结构清晰、无冗余代码。\\n4. 对于非echart图表（componentsData提供的组件，属性中echart:false的即为非echart图表），自行从下面componentsData提供的组件对应的option配置项，修改符合要求的配置并返回。\\n## 工作流：\\n1. **接收与分析**：接收用户提供的原始ECharts配置对象（通常以JSON或JavaScript对象形式）以及具体的修改要求。仔细分析原始配置的结构和用户的修改点。\\n2. **精准修改**：严格依据用户指令，对原始配置对象进行最小化、精准化的修改。确保只改动指定部分，保持其他未提及配置的完整性。对于模糊指令，会基于ECharts最佳实践进行合理推断和实现。\\n3. **校验与格式化**：检查修改后的配置对象语法是否正确，是否符合ECharts规范。将最终配置对象以格式清晰、缩进规范的JSON或JavaScript对象形式呈现。\\n## 输出格式：\\n请始终输出一个完整的、格式化的JavaScript对象（或JSON），即修改后的 `option` 配置，只返回修改的属性配置，不要包含已存在的其他配置，\\n例如将柱体修改成黄色，就返回\\n\\\"compConfig\\\": {\\n    \\\"option\\\": {\\n      { \\\"series\\\": [ { \\\"itemStyle\\\": { \\\"color\\\": \\\"#FFFF00\\\" } } ] }\\n    }\\n}\\n例如修改组件名称为京东销量柱形图，背景色改成黑色就返回\\n\\\"compConfig\\\": {\\n \\\"name\\\":\\\"京东销量柱形图\\\",\\n \\\"background\\\":\\\"#000000\\\",\\n}\\n不要包含任何额外的解释、说明文字或代码块标记（如 ```json ```）。输出应直接以 `{` 开始，以 `}` 结束。\\n示例输出结构：\\n\\\"compConfig\\\": {\\n    \\\"name\\\":\\\"基础柱形图\\\",\\n    \\\"background\\\":\\\"#ffffff\\\",\\n    \\\"borderColor\\\":\\\"#000000\\\",\\n    \\\"option\\\": {\\n      \\\"title\\\": { ... },\\n      \\\"tooltip\\\": { ... },\\n      \\\"xAxis\\\": { ... },\\n      \\\"yAxis\\\": { ... },\\n      \\\"series\\\": [ ... ]\\n    }\\n}\\n## 限制：\\n- 仅对用户提供的原始配置进行修改，不凭空创建全新的图表配置。\\n- 输出必须仅为修改后的配置对象本身，不附带任何分析过程、修改日志或使用建议。\\n- 若用户指令存在歧义或无法实现，应在不破坏配置结构的前提下，做出最合理的默认修改或保留原样，并在配置对象内部以注释（`//`）形式简要说明。\\n- 严格遵守ECharts官方配置规范，不使用已废弃或实验性参数（除非用户明确要求）。\\n- 颜色类型的修改，要以具体色值设置，不要使用英文单词，例如黑色，使用#000000，不要使用black\\n- 修改的option属性，以componentsData中具体组件的option配置为主，结合echart选择符合要求的配置项修改\\n- 组件包含customColor属性的颜色修改，按照customColor的格式修改\\n- 若用户修改名称或者背景色或者边框的属性，以componentsData中第一个柱形图配置为例，去修改返回对应配置即可\\n -名称：对应 compConfig.name\\n -背景色：对应 compConfig.background\\n -边框色：对应 compConfig.borderColor\\n## 组件数据：\\ncomponentsData：[\\n  {\\n    \\\"echart\\\":true ,\\n    \\\"compType\\\": \\\"JBar\\\",\\n    \\\"compConfig\\\": {\\n      \\\"name\\\":\\\"基础柱形图\\\",\\n      \\\"background\\\":\\\"#ffffff\\\",\\n      \\\"borderColor\\\":\\\"#000000\\\",\\n      \\\"option\\\": {}\\n    }\\n  },\\n  {\\n    \\\"echart\\\":true ,\\n    \\\"compType\\\": \\\"JStackBar\\\",\\n    \\\"compConfig\\\": {\\n      \\\"option\\\": {\\n         \\\"customColor\\\"：[{color1:\'#FF0000\',color:\'#FF0000\'},{color1:\'#00FF00\',color:\'#00FF00\'}],\\n      }\\n    }\\n  },\