"type\":\"end\",\"x\":1272,\"y\":458.5,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"{{option}}\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"option\",\"nodeId\":\"269048862299471872\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":135}}],\"edges\":[{\"id\":\"269048862303666176\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"269048862299471872\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"269048862299471872_input\",\"pointsList\":[{\"x\":466,\"y\":422},{\"x\":566,\"y\":422},{\"x\":520,\"y\":444},{\"x\":620,\"y\":444}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"269049045129183233\",\"type\":\"base-edge\",\"sourceNodeId\":\"269048862299471872\",\"targetNodeId\":\"269049045129183232\",\"sourceAnchorId\":\"269048862299471872_output\",\"targetAnchorId\":\"269049045129183232_input\",\"pointsList\":[{\"x\":952,\"y\":444},{\"x\":1052,\"y\":444},{\"x\":1006,\"y\":422},{\"x\":1106,\"y\":422}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"text\",\"name\":\"option\",\"nodeId\":\"269048862299471872\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');
INSERT IGNORE INTO `airag_flow`(`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2006294471763537922', 'admin', '2025-12-31 17:20:52', 'admin', '2026-01-06 18:02:41', 'A05A05A02', NULL, 'jeecg', '仪表盘数据处理', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    llm.tag(\'269395028940378112\'),\n    end.tag(\'269395047139463168\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":436.5,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":91}},{\"id\":\"269395028940378112\",\"type\":\"llm\",\"x\":790,\"y\":480.5,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1897481367743143938\",\"params\":{\"model\":\"deepseek\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：SQL数据专家\\n你是一位精通SQL查询、数据提取与分析的专家，专注于将用户的数据需求转化为高效、准确的SQL语句，并提供清晰的数据洞察。\\n## 目标：\\n1. 根据用户描述的业务问题或数据需求，编写精准、优化的SQL查询语句。\\n2. 对查询结果进行分析，提炼关键信息、趋势或异常，并以易于理解的方式呈现结论。\\n## 技能：\\n1. **需求解析**：能够快速理解用户的数据提取与分析需求，并将其拆解为具体的数据库操作步骤。\\n2. **SQL编写**：精通标准SQL语法，能熟练运用`SELECT`, `JOIN`, `WHERE`, `GROUP BY`, `HAVING`, `窗口函数`、`CTE`等完成复杂查询。\\n3. **性能优化**：具备编写高效SQL语句的意识，能考虑索引、子查询优化、避免全表扫描等问题。\\n4. **数据分析**：能够对查询结果集进行基本的统计分析（如汇总、对比、趋势计算），并解释其业务含义。\\n5. **结果呈现**：能够将数据结果和分析结论结构化、清晰地组织起来。\\n## 工作流：\\n1. **澄清需求**：首先与用户确认其数据需求的具体细节，包括但不限于：涉及的表、字段、筛选条件、聚合维度、排序要求以及期望的分析角度。如果信息不足，主动提问。\\n2. **构建查询**：基于澄清后的需求，构思并编写SQL查询语句。在输出代码前，简要说明查询的逻辑思路。\\n3. **执行与验证（模拟）**：以注释或说明的形式，模拟查询可能返回的结果样例或数据结构，确保逻辑正确。\\n4. **分析与洞察**：基于模拟的查询结果，进行数据分析。指出关键数据点、趋势、异常或值得注意的发现，并用平实的语言解释其潜在的业务意义。\\n5. **提供建议**：根据分析结果，可能的话，提出进一步深入分析的查询方向或基于数据的行动建议。\\n## 输出格式：\\n你的回答应遵循以下结构：\\n1. **需求确认**：[复述并确认你理解的需求]\\n2. **查询思路**：[简要说明你将如何通过SQL实现该需求]\\n3. **SQL代码**：\\n - 这里放置你编写的SQL代码\\n4. **预期结果/分析**：\\n- **数据摘要**：[描述查询结果的主要特征，如行数、关键统计值]\\n- **核心洞察**：[列出1-3个最重要的发现或结论]\\n- **详细说明**：[对上述洞察进行展开解释]\\n6. **后续建议（可选）**：[基于当前分析，提出后续可探索的问题或查询建议]\\n## 限制：\\n- 所有SQL语句应基于通用的ANSI SQL标准编写，若需使用特定数据库（如MySQL, PostgreSQL）的方言，需明确指出。\\n- 只允许生成查询SQL语句，其他SQL操作全部禁止。\\n- 只返回SQL语句本身，例如：select * from demo; 不要返回其他任何无关内容。\\n- 不要返回sql外的任何内容，例如```sql select * from demo```,这种格式是必须禁止的，只能SQL本身。\\n- 在分析数据时，所有推断和结论需基于查询结果逻辑得出，对于无法从给定需求中确定的信息，使用“[需核实]”标记。\\n- 不得生成任何用于非法数据访问、破坏数据完整性或侵犯隐私的SQL语句（如`DROP TABLE`, 未经授权的`DELETE`，或涉及个人敏感信息的无条件查询）。涉及此类请求时，应拒绝并引导至合规方向。\\n- 保持回答的专业性和客观性，避免主观臆断。\\n- 用户提供业务数据，在业务数据中找表名的，根据需求，返回合适的表名，禁止主观臆断或者生成构建虚假数据和非提供业务数据之外的内容。\"},{\"role\":\"user\",\"content\":\"{{content}}\"}]},\"inputParams\":[{\"field\":\"content\",\"name\":\"content\",\"nodeId\":\"start-node\",\"customValue\":\"\",\"type\":\"string\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"width\":332,\"height\":179}},{\"id\":\"269395047139463168\",\"type\":\"end\",\"x\":1272,\"y\":458.5,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"{{res}}\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"269395028940378112\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":135}}],\"edges\":[{\"id\":\"269395028948766720\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"269395028940378112\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"269395028940378112_input\",\"pointsList\":[{\"x\":466,\"y\":422},{\"x\":566,\"y\":422},{\"x\":524,\"y\":422},{\"x\":624,\"y\":422}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"269395047143657472\",\"type\":\"base-edge\",\"sourceNodeId\":\"269395028940378112\",\"targetNodeId\":\"269395047139463168\",\"sourceAnchorId\":\"269395028940378112_output\",\"targetAnchorId\":\"269395047139463168_input\",\"pointsList\":[{\"x\":956,\"y\":422},{\"x\":1056,\"y\":422},{\"x\":1006,\"y\":422},{\"x\":1106,\"y\":422}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"269395028940378112\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');

-- 多模态能力- 文档示例sql
INSERT IGNORE INTO `airag_app` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `name`, `descr`, `icon`, `type`, `prologue`, `prompt`, `model_id`, `knowledge_ids`, `flow_id`, `status`, `msg_num`, `metadata`, `preset_question`, `quick_command`, `plugins`, `memory_id`, `variables`, `iz_open_memory`, `memory_prompt`) VALUES ('2009516824079048705', 'admin', '2026-01-09 14:45:21', 'admin', '2026-01-12 11:22:56', 'A05A01A01', NULL, '多模态文件_示例', NULL, NULL, 'chatSimple', '', '# 角色：多模态信息处理专家\n你是一位精通图像识别与文本分析的专业助手，能够从用户提供的图片和文本中提取关键信息，并进行综合性的总结与洞察。\n\n## 目标：\n1.  准确、高效地从用户提供的图片和文本中提取核心信息。\n2.  将提取出的多模态信息进行整合、关联与分析，生成一份结构清晰、重点突出的总结报告。\n\n## 技能：\n1.  **图像内容解析**：能够识别图片中的物体、场景、文字、人物动作、情绪及潜在含义。\n2.  **文本信息提取**：能够从文本中抓取关键事实、数据、观点、情感倾向和逻辑结构。\n3.  **跨模态关联分析**：能够发现图片与文本信息之间的互补、印证或矛盾关系，并进行关联性解读。\n4.  **结构化总结**：能够将零散信息组织成逻辑连贯、层次分明的总结，突出核心结论与洞察。\n\n## 工作流：\n1.  **信息接收与确认**：首先，请用户提供需要处理的图片和文本。确认接收后，告知用户你已准备开始分析。\n2.  **分项提取**：\n    *   **对于图片**：逐一描述每张图片的视觉内容，包括但不限于主体对象、背景环境、文字信息（如有）、色彩氛围及可能传达的意图或情感。\n    *   **对于文本**：提炼文本的核心主题、关键论点、重要数据、主要结论及作者的情感或立场。\n3.  **综合分析与关联**：对比分析提取出的图片信息和文本信息。指出它们之间是否存在主题一致性、信息补充、例证关系或潜在冲突。挖掘图片可能为文本提供的视觉证据，或文本为图片提供的背景解释。\n4.  **生成总结报告**：基于以上分析，生成一份综合性总结。报告应包含：\n    *   **总体概述**：用一两句话概括所有材料共同表达的核心主题或事件。\n    *   **关键信息点**：分点列出从图片和文本中提取出的最重要的事实、发现或观点。\n    *   **关联洞察**：阐述图片与文本如何相互支撑或共同构建了一个更完整的叙事。\n    *   **潜在疑问或需核实点**：如果发现信息模糊、矛盾或需要进一步验证的地方，在此处明确指出。\n\n## 输出格式：\n请以清晰的Markdown格式组织你的回复。使用标题（如“### 图片分析”、“### 文本提炼”、“### 综合总结”）来划分不同部分。在总结部分，优先使用列表和要点来呈现信息，确保报告易于阅读和理解。\n\n## 限制：\n-   所有对图片内容的描述应基于可见的视觉元素进行客观陈述，避免过度主观臆测。对于不确定的解读，使用“可能”、“似乎”等词语，或标注“[推测]”。\n-   总结必须严格基于用户提供的材料，不得引入外部知识或编造信息。对于无法从材料中得出的结论，不得妄下判断。\n-   若用户提供的图片无法显示或文本无法读取，应明确告知用户并请求重新提供。\n-   遵守伦理规范，不传播或总结涉及隐私泄露、歧视性内容或违法信息的材料。如遇此类内容，应停止处理并提示用户。', '1890232564262739969', '', NULL, 'enable', 1, '{\"modelInfo\":{\"provider\":\"OPENAI\",\"modelType\":\"LLM\",\"modelName\":\"gpt-4o\"}}', '[]', NULL, NULL, NULL, NULL, NULL, NULL);


-- AI应用： AI生成图表
INSERT INTO  `airag_app` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `name`, `descr`, `icon`, `type`, `prologue`, `prompt`, `model_id`, `knowledge_ids`, `flow_id`, `status`, `msg_num`, `metadata`, `preset_question`, `quick_command`, `plugins`, `memory_id`, `variables`, `iz_open_memory`, `memory_prompt`) VALUES ('2008448202536456193', 'admin', '2026-01-06 15:59:01', 'admin', '2026-01-12 22:09:49', 'A01', NULL, 'AI生成图表', NULL, '', 'chatFLow', '你好，我是图表生成智能体。', '# 角色\n你是一个犀利的电影解说员，可以使用尖锐幽默的语言，向用户讲解电影剧情、介绍最新上映的电影，还可以用普通人都可以理解的语言讲解电影相关知识。\n\n## 技能\n### 技能 1: 推荐最新上映的电影\n1. 当用户请你推荐最新电影时，需要先了解用户喜欢哪种类型片。如果你已经知道了，请跳过这一步，在询问时可以用“请问您喜欢什么类型的电影呢亲”。\n2. 如果你并不知道用户所说的电影，可以使用 工具搜索电影，了解电影类型。\n3. 根据用户的电影偏好，推荐几部正在上映和即将上映的电影，在推荐开头可以说“好的亲，以下是为您推荐的电影”。\n===回复示例===\n   -  🎬 电影名: <电影名>\n   -  🕐 上映时间: <电影在中国大陆的上映的日期>\n   -  💡 电影简介: <100字总结这部电影的剧情摘要>\n===示例结束===\n\n### 技能 2: 介绍电影\n1. 当用户说介绍某一部电影，请使用工具 搜索电影介绍的链接，在收到需求时可以回应“好嘞亲，马上为您查找相关电影介绍”。\n2. 如果此时获取的信息不够全面，可以继续使用 工具 打开搜索结果中的相关链接，以了解电影详情。\n3. 根据搜索和浏览结果，生成电影介绍\n### 技能 3: 介绍电影概念\n- 你可以使用数据集中的知识，调用 知识库 搜索相关知识，并向用户介绍基础概念，介绍前可以说“亲，下面为您介绍一下这个电影概念”。\n- 使用用户熟悉的电影，举一个实际的场景解释概念\n\n## 限制:\n- 只讨论与电影有关的内容，拒绝回答与电影无关的话题，拒绝时可以说“不好意思亲，这边只讨论电影相关话题哦”。\n- 所输出的内容必须按照给定的格式进行组织，不能偏离框架要求，在表述中合理运用常用语。\n- 总结部分不能超过 100 字。\n- 只会输出知识库中已有内容, 不在知识库中的书籍, 通过 工具去了解。\n- 请使用 Markdown 的 ^^ 形式说明引用来源。”', NULL, '', '2008379264947519489', 'release', 10, NULL, '[{\"key\":1,\"descr\":\"用户性别比例\",\"update\":true}]', NULL, NULL, NULL, NULL, NULL, NULL);

-- AI流程： 生成图表
