ointsList\":[{\"x\":1020,\"y\":459},{\"x\":1120,\"y\":459},{\"x\":1102,\"y\":605},{\"x\":1202,\"y\":605}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"index\",\"name\":\"d\",\"nodeId\":\"271481764802605056\",\"type\":\"number\"},{\"customValue\":\"\",\"field\":\"text\",\"name\":\"回复\",\"nodeId\":\"271548210211192832\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');

-- MCP插件： 数据库插件
INSERT IGNORE INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('2006287314794676226', NULL, '数据库插件', '用于执行数据库操作', 'plugin', 'api', NULL, '', '[{\"name\":\"queryTableMetadata\",\"description\":\"用于查询表的表结构（元数据）\",\"path\":\"/airag/mcp/database/queryTableMetadata\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"tableName\",\"description\":\"表名\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"success\",\"description\":\"是否成功\",\"type\":\"Boolean\"},{\"name\":\"message\",\"description\":\"若失败则返回失败原因\",\"type\":\"String\"},{\"name\":\"result.tableName\",\"description\":\"表名（数据库实际表名）\",\"type\":\"Object\"},{\"name\":\"result.tableComment\",\"description\":\"表注释（业务含义）\",\"type\":\"Object\"},{\"name\":\"result.columns[].columnName\",\"description\":\"字段名\",\"type\":\"Array\"},{\"name\":\"result.columns[].columnComment\",\"description\":\"字段注释（核心，帮助大模型理解业务）\",\"type\":\"Array\"},{\"name\":\"result.columns[].dataType\",\"description\":\"数据类型（如varchar、int、datetime）\",\"type\":\"Array\"},{\"name\":\"result.columns[].isPrimaryKey\",\"description\":\"是否主键\",\"type\":\"Array\"}]},{\"name\":\"sqlExecute\",\"description\":\"用于执行 SQL 语句，仅能支持执行SELECT语句，不要输入注释等无关信息。\",\"path\":\"/airag/mcp/database/sqlExecute\",\"method\":\"POST\",\"enabled\":true,\"parameters\":[{\"name\":\"sql\",\"description\":\"\",\"type\":\"String\",\"location\":\"Body\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"success\",\"description\":\"是否成功\",\"type\":\"Boolean\"},{\"name\":\"message\",\"description\":\"若失败则返回失败原因\",\"type\":\"String\"},{\"name\":\"result\",\"description\":\"返回查询的结果，是个对象数组，数组的每一项都是一条数据，每条数据的key都是传入的查询的列。\",\"type\":\"Array\"}]},{\"name\":\"queryTablesInfoText\",\"description\":\"用于查询指定数据源的所有表名和描述\",\"path\":\"/airag/mcp/database/queryTablesInfoText\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"dbSourceKey\",\"description\":\"数据源code，不填则系统默认\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[]}]', 'enable', 1, '{\"tokenParamName\":\"X-Access-Token\",\"tool_count\":3,\"authType\":\"token\",\"tokenParamValue\":\"\"}', 'admin', '2025-12-31 16:52:26', 'admin', '2026-01-12 19:45:24', 'A01', NULL);


