INSERT IGNORE INTO `sys_permission` (`id`, `parent_id`, `name`, `url`, `component`, `is_route`, `component_name`, `redirect`, `menu_type`, `perms`, `perms_type`, `sort_no`, `always_show`, `icon`, `is_leaf`, `keep_alive`, `hidden`, `hide_tab`, `description`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `rule_flag`, `status`, `internal_or_external`) VALUES ('2010623918706446338', '1892553163993931777', 'AI写作', '/airag/aiwriter/AiWriter', 'super/airag/aiwriter/AiWriter', 1, '', NULL, 1, NULL, '0', 9.00, 0, 'ant-design:edit-filled', 1, 0, 0, 0, NULL, 'admin', '2026-01-12 16:04:32', 'admin', '2026-01-12 16:04:50', 0, 0, NULL, 0);
INSERT IGNORE INTO `airag_app` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `name`, `descr`, `icon`, `type`, `prologue`, `prompt`, `model_id`, `knowledge_ids`, `flow_id`, `status`, `msg_num`, `metadata`, `preset_question`, `quick_command`, `plugins`, `memory_id`, `variables`, `iz_open_memory`, `memory_prompt`) VALUES ('2010634128233779202', 'admin', '2026-01-12 16:45:07', 'admin', '2026-01-14 19:56:22', 'A05A01A01', NULL, 'AI写作_示例', NULL, NULL, 'chatSimple', '', '## 角色：精准内容与段落配图生成专家\n你是一位专业的内容生成助手，能够严格按照用户指定的格式、语气、长度和语言要求，直接输出精准匹配的最终内容，并为每个独立段落配上 1 张高相关度的图片。\n## 任务类型识别\n1. 回复类任务：当用户提供原始问题和参考回复时，仅基于给定内容生成精准回复，不得额外添加无关信息（如通知、背景介绍等）。\n2. 文章类任务：当用户提供主题时，撰写结构清晰、内容准确的完整文章，可包含引言、主体段落、总结等部分。\n## 目标\n1. **严格遵循指令**：完全按照用户指定的格式、语气、语言和长度要求生成内容。\n2. **直接输出结果**：仅输出符合要求的正文内容和对应的段落配图，不包含任何额外的标题、解释、道歉或中间过程。\n3. **逐段精准配图**：为每一个独立的段落匹配 1 张与该段内容强相关的图片，图片直接插入到对应段落的末尾，而非统一放在全文结尾。\n4. **适配两种模式**：既能独立创作短文并逐段配图，也能基于给定的原文和参考内容生成精准回复并逐段配图。\n## 核心规则\n1. 严格匹配要求：必须完全遵循用户指定的格式、语气、长度和语言要求。\n\n## 技能\n1. **精准指令解析**：准确识别用户的创作模式（独立创作 / 回复）、格式（消息 / 邮件等）、语气（友善 / 专业等）、语言（中文 / 英文等）和长度（短 / 中 / 长）。\n2. **无冗余输出**：仅生成符合要求的正文内容，不添加任何指令外的信息。\n3. **独立创作能力**：针对独立创作需求，能围绕核心主题生成结构清晰、语言流畅的短文。\n4. **精准回复能力**：针对回复需求，能基于原文和参考内容生成精准匹配的简短回复。\n5. **逐段配图能力**：为每个独立段落提取精准关键词，调用图片工具完成搜索，图片直接插入到对应段落的末尾。\n6. **避免搜索死循环**：每个图片仅使用 1-2 个精准关键词一次搜索完成，不反复调整关键词。\n7. **内容精准性**：回复类内容必须与参考内容完全一致，不得扩写；文章类内容必须准确、专业，不虚构事实。\n## 工作流（内部执行，不对外展示）\n1. **识别需求类型**：判断用户需求是独立创作短文，还是基于给定内容生成回复。\n2. **解析参数要求**：提取并确认格式、语气、语言、长度等所有约束条件。\n3. **生成精准内容**：\n  - 独立创作：围绕核心主题，生成符合长度和语气要求的正文，并自然分段。\n  - 回复：基于原文和参考内容，生成精准匹配的简短回复，并自然分段。\n4. **逐段匹配配图**：为每个独立段落提取 1-2 个与该段内容强相关的关键词，调用图片工具完成搜索。\n5. **整合输出**：将图片以路径的方式直接插入到对应段落的末尾，仅输出最终的图文内容，不包含任何额外信息或中间过程。\n## 限制\n- 禁止输出标题、解释、过程或额外说明。\n- 只对重点内容配图，非重点内容不配图。\n- 图片必须与重点内容高度相关。\n- 每个重点内容只配 1 张图，避免重复搜索。\n- 图片插入在重点内容附近，不集中放在结尾。\n- 语言必须符合用户指定的要求。', '1897481367743143938', '', NULL, 'enable', 1, '{\"modelInfo\":{\"provider\":\"DEEPSEEK\",\"modelType\":\"LLM\",\"modelName\":\"deepseek-chat\"}}', '[]', NULL, '[{\"pluginId\":\"1988208474780168193\",\"pluginName\":\"图片搜索\",\"category\":\"plugin\"}]', '', NULL, 1, NULL);

-- 示例OCR提示词修改
UPDATE `airag_flow` SET   `chain` = 'THEN(\n    start.tag(\'start-node\'),\n    SWITCH(switch.tag(\'167880707187527680\')).to(\n        end.tag(\'167880856269869056\'),\n        THEN(\n            code_167881149430747136.tag(\'code_167881149430747136\'),\n            llm.tag(\'167881839356006400\'),\n            end.tag(\'167880661561888768\')\n        ).tag(\"code_167881149430747136\")\n    ).tag(\'167880707187527680\')\n).tag(\"start-node\")', `design` = '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":420,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":true},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"height\":90,\"width\":332}},{\"id\":\"167880661561888768\",\"type\":\"end\",\"x\":1474,\"y\":341,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"\",\"outputType\":\"default\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"data\",\"nodeId\":\"167881839356006400\"}],\"height\":112,\"width\":332}},{\"id\":\"167880707187527680\",\"type\":\"switch\",\"x\":681,\"y\":232,\"properties\":{\"text\":\"条件分支\",\"options\":{\"if\":[{\"logic\":\"AND\",\"conditions\":[{\"nodeId\":\"start-node\",\"field\":\"images\",\"operator\":\"EMPTY\",\"value\":\"\",\"type\":\"picture\"}],\"next\":\"167880856269869056\"}],\"else\":{\"next\":\"code_167881149430747136\"}},\"inputParams\":[],\"outputParams\":[{\"field\":\"index\",\"name\":\"分支索引\",\"type\":\"number\"}],\"height\":116,\"width\":332}},{\"id\":\"167880856269869056\",\"type\":\"end\",\"x\":1207,\"y\":206,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":true,\"outputContent\":\"{\\n    \\\"message\\\": \\\"请提供图片\\\"\\n  }\",\"outputType\":\"text\"},\"inputParams\":[],\"outputParams\":[],\"height\":112,\"width\":332}},{\"id\":\"code_167881149430747136\",\"type\":\"code\",\"x\":937,\"y\":458,\"properties\":{\"text\":\"脚本执行\",\"options\":{\"codeType\":\"groovy\",\"code\":\"def main(Map params) {\\n    def newQuestion = params.question\\n    if (!params.question) {\\n        newQuestion = \\\"从图片中提取文字\\\"\\n    }\\n    return [result: newQuestion]\\n}\\n\"},\"inputParams\":[{\"field\":\"content\",\"name\":\"question\",\"nodeId\":\"start-node\",\"customValue\":\"\",\"type\":\"string\"}],\"outputParams\":[{\"field\":\"result\",\"name\":\"返回结果\",\"type\":\"string\"}],\"height\":156,\"width\":332}},{\"id\":\"167881839356006400\",\"type\":\"llm\",\"x\":1318,\"y\":605,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：OCR工具\\n作为一个智能OCR工具，你的主要职责是从图片中提取文字并将其输出为结构化数据。\\n## 目标：\\n1. 精确识别和提取图片中的文字信息。\\n2. 将提取的文字转换为结构化数据格式。\\n## 技能：\\n1. 高效的图像处理能力。\\n2. 精确的文字识别算法。\\n3. 数据格式化与输出能力。\\n## 工作流：\\n1. 输入图片，进行预处理（如去噪、二值化）。\\n2. 应用OCR算法识别图片中的文字，并记录识别结果。\\n3. 将识别的文字整理成结构化数据格式，如JSON或CSV。\\n## 输出格式：必须严格遵循以下JSON格式，不得添加任何额外字段或自由文本。\\n\\n{\\n    \\\"text\\\": \\\"提取的内容\\\",\\n    \\\"metadata\\\": {\\\"source\\\": \\\"图片来源\\\", \\\"timestamp\\\": \\\"提取时间\\\"}\\n  }\\n## 限制：\\n- 仅限于合法和合规的图片内容提取。\\n- 不得保存用户上传的图片数据。\\n- 需确保输出的数据准确无误，标注所有数据来源。\\n- 输出必须严格符合上述格式，字段名和层级结构不得随意更改。\"},{\"role\":\"user\",\"content\":\"{{question}}\"}],\"showToolExecution\":false},\"inputParams\":[{\"field\":\"images\",\"name\":\"images\",\"nodeId\":\"start-node\",\"customValue\":\"\",\"type\":\"picture\"},{\"field\":\"result\",\"name\":\"question\",\"nodeId\":\"code_167881149430747136\",\"customValue\":\"\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":178,\"width\":332}}],\"edges\":[{\"id\":\"167880707195916288\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"167880707187527680\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"167880707187527680_input\",\"pointsList\":[{\"x\":466,\"y\":406},{\"x\":566,\"y\":406},{\"x\":415,\"y\":205},{\"x\":515,\"y\":205}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"167880856274063360\",\"type\":\"base-edge\",\"sourceNodeId\":\"167880707187527680\",\"targetNodeId\":\"167880856269869056\",\"sourceAnchorId\":\"167880707187527680_source_if\",\"targetAnchorId\":\"167880856269869056_input\",\"pointsList\":[{\"x\":847,\"y\":239},{\"x\":947,\"y\":239},{\"x\":941,\"y\":181},{\"x\":1041,\"y\":181}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"167881149434941440\",\"type\":\"base-edge\",\"sourceNodeId\":\"167880707187527680\",\"targetNodeId\":\"code_167881149430747136\",\"sourceAnchorId\":\"167880707187527680_source_else\",\"targetAnchorId\":\"code_167881149430747136_input\",\"pointsList\":[{\"x\":847,\"y\":265},{\"x\":947,\"y\":265},{\"x\":671,\"y\":411},{\"x\":771,\"y\":411}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"167881839356006401\",\"type\":\"base-edge\",\"sourceNodeId\":\"code_167881149430747136\",\"targetNodeId\":\"167881839356006400\",\"sourceAnchorId\":\"code_167881149430747136_output\",\"targetAnchorId\":\"167881839356006400_input\",\"pointsList\":[{\"x\":1103,\"y\":411},{\"x\":1203,\"y\":411},{\"x\":1052,\"y\":547},{\"x\":1152,\"y\":547}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"167882293611712512\",\"type\":\"base-edge\",\"sourceNodeId\":\"167881839356006400\",\"targetNodeId\":\"167880661561888768\",\"sourceAnchorId\":\"167881839356006400_output\",\"targetAnchorId\":\"167880661561888768_input\",\"pointsList\":[{\"x\":1484,\"y\":547},{\"x\":1584,\"y\":547},{\"x\":1208,\"y\":316},{\"x\":1308,\"y\":316}],\"properties\":{\"runStatus\":\"\"}}]}', `status` = 'enable', `metadata` = '{\"outputs\":[{\"field\":\"text\",\"name\":\"data\",\"nodeId\":\"167881839356006400\"},{\"field\":\"outputText\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":true,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}' WHERE `id` = '1904779811574784002';

