UPDATE `airag_mcp` SET `icon` = NULL, `name` = '数据库插件', `descr` = '用于执行数据库操作', `category` = 'plugin', `type` = 'api', `endpoint` = '', `headers` = '{\"X-Sign\":\"true\"}', `tools` = '[{\"name\":\"queryTableMetadata\",\"description\":\"用于查询表的表结构（元数据）\",\"path\":\"/airag/mcp/database/queryTableMetadata\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"tableName\",\"description\":\"表名\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"},{\"name\":\"dbSourceKey\",\"description\":\"数据源key\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"success\",\"description\":\"是否成功\",\"type\":\"Boolean\"},{\"name\":\"message\",\"description\":\"若失败则返回失败原因\",\"type\":\"String\"},{\"name\":\"result.tableName\",\"description\":\"表名（数据库实际表名）\",\"type\":\"Object\"},{\"name\":\"result.tableComment\",\"description\":\"表注释（业务含义）\",\"type\":\"Object\"},{\"name\":\"result.columns[].columnName\",\"description\":\"字段名\",\"type\":\"Array\"},{\"name\":\"result.columns[].columnComment\",\"description\":\"字段注释（核心，帮助大模型理解业务）\",\"type\":\"Array\"},{\"name\":\"result.columns[].dataType\",\"description\":\"数据类型（如varchar、int、datetime）\",\"type\":\"Array\"},{\"name\":\"result.columns[].isPrimaryKey\",\"description\":\"是否主键\",\"type\":\"Array\"}]},{\"name\":\"sqlExecute\",\"description\":\"用于执行 SQL 语句，仅能支持执行SELECT语句，不要输入注释等无关信息。\",\"path\":\"/airag/mcp/database/sqlExecute\",\"method\":\"POST\",\"enabled\":true,\"parameters\":[{\"name\":\"sql\",\"description\":\"要执行的SQL\",\"type\":\"String\",\"location\":\"Body\",\"required\":true,\"defaultValue\":\"\"},{\"name\":\"dbSourceKey\",\"description\":\"数据源key\",\"type\":\"String\",\"location\":\"Body\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"success\",\"description\":\"是否成功\",\"type\":\"Boolean\"},{\"name\":\"message\",\"description\":\"若失败则返回失败原因\",\"type\":\"String\"},{\"name\":\"result\",\"description\":\"返回查询的结果，是个对象数组，数组的每一项都是一条数据，每条数据的key都是传入的查询的列。\",\"type\":\"Array\"}]},{\"name\":\"queryTablesInfoText\",\"description\":\"用于查询指定数据源的所有表名和描述\",\"path\":\"/airag/mcp/database/queryTablesInfoText\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"dbSourceKey\",\"description\":\"数据源code，不填则系统默认\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[]},{\"name\":\"queryDataSourceInfoText\",\"description\":\"用于查询所有数据源的信息，不需要传递参数。\",\"path\":\"/airag/mcp/database/queryDataSourceInfoText\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[],\"responses\":[]},{\"name\":\"queryDataSourceType\",\"description\":\"获取默认数据源或指定数据的数据库类型\",\"path\":\"/airag/mcp/database/queryDataSourceType\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"dbSourceKey\",\"description\":\"数据源key，若为空则系统默认\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[]},{\"name\":\"getChartExampleJson\",\"description\":\"用户获取图表示例数据\",\"path\":\"/airag/mcp/database/getChartExampleJson\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"type\",\"description\":\"图表类型，多个用英文逗号分割\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[]}]', `status` = 'enable', `synced` = 1, `metadata` = '{\"tokenParamName\":\"X-Access-Token\",\"tool_count\":6,\"authType\":\"token\",\"tokenParamValue\":\"\"}', `create_by` = 'admin', `create_time` = '2025-12-31 16:52:26', `update_by` = 'admin', `update_time` = '2026-01-16 17:00:51', `sys_org_code` = 'A01', `tenant_id` = NULL WHERE `id` = '2006287314794676226';

